import React, { useContext, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { useSnackbar } from "notistack";
import Box from "@mui/material/Box";
import Card from "@mui/material/Card";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";
import Button from "@mui/material/Button";
import ButtonBase from "@mui/material/ButtonBase";
import Radio from "@mui/material/Radio";
import RadioGroup from "@mui/material/RadioGroup";
import FormControlLabel from "@mui/material/FormControlLabel";
import CircularProgress from "@mui/material/CircularProgress";
import TextField from "@mui/material/TextField";
import DialogContent from "@mui/material/DialogContent";
import DialogActions from "@mui/material/DialogActions";
import List from "@mui/material/List";
import ListItem from "@mui/material/ListItem";
import ListItemText from "@mui/material/ListItemText";
import IconButton from "@mui/material/IconButton";
import CheckCircleOutlined from "@mui/icons-material/CheckCircleOutlined";
import MenuBookOutlined from "@mui/icons-material/MenuBookOutlined";
import CloseOutlined from "@mui/icons-material/CloseOutlined";
import VolumeUpOutlined from "@mui/icons-material/VolumeUpOutlined";
import VideocamOutlined from "@mui/icons-material/VideocamOutlined";
import MicOutlined from "@mui/icons-material/MicOutlined";
import StopCircleOutlined from "@mui/icons-material/StopCircleOutlined";
import DeleteOutlined from "@mui/icons-material/DeleteOutlined";
import DownloadOutlined from "@mui/icons-material/DownloadOutlined";
import VisibilityOutlined from "@mui/icons-material/VisibilityOutlined";
import InsertDriveFileOutlined from "@mui/icons-material/InsertDriveFileOutlined";
import { AppContext, reUseBlocContent } from "../../../base/AppContext";
import AppDialog from "../../components/dialogs/AppDialog";
import { DIALOG_PRIMARY_BUTTON_SX } from "../../components/dialogs/dialogToneStyles";
import { BlocStudentAttempt, QuizStudentQuestion } from "../../bloc/BlocStudentAttempt";
import { QuizLessonAttachment } from "../../../api/QuizLessonApi";
import UIStream from "../../components/common/UIStream";
import { quizErrorMessage } from "../../../quiz-net/quizErrors";

// Trang "Làm bài" (khu vực Học sinh, /app/student/tests/:testId/take - Task 6 backend). Vào trang
// tự start/resume attempt (idempotent bên backend). Chọn đáp án lưu ngay (progressive save qua
// BlocStudentAttempt.saveAnswer, không chờ nộp bài mới lưu) - học sinh thoát giữa chừng rồi quay
// lại làm tiếp cũng không mất đáp án đã chọn. Nộp bài xong hiện luôn điểm số (đây là LẦN DUY NHẤT
// học sinh thấy điểm - backend task 6 không có endpoint xem lại kết quả sau đó, xem Tests.tsx).
//
// "Xem lại bài học" (task 2026-09-01): CÙNG 1 trang này phục vụ cả lúc đang làm bài lẫn sau khi đã
// nộp (không có trang kết quả riêng, xem đoạn trên) - danh sách câu hỏi vẫn hiện dưới điểm số sau
// khi nộp (radio chuyển disabled, chỉ xem lại lựa chọn cũ, không có trang "review" khác). Mỗi câu
// hỏi có nút mở Dialog xem nội dung Bài học nó thuộc về (StudentLessonApi.java qua
// BlocStudentAttempt.loadLesson/loadLessonImage) - dùng chung 1 Dialog cho cả 2 giai đoạn.
//
// GIAO DIỆN LÀM BÀI "1 CÂU/MÀN HÌNH" (2026-09-06, theo yêu cầu của anh: "đề dài quá làm học sinh
// mất thời gian scroll... thiết kế kiểu next/prev từng câu, câu nào đã làm thì đánh dấu check, bấm
// câu chưa làm/đã làm để move đến câu đó làm/sửa đáp án") - CHỈ áp dụng lúc ĐANG làm bài
// (`result == null`): 1 bảng chọn nhanh (hàng ngang, tự xuống dòng - đã chọn qua AskUserQuestion
// thay vì sidebar cố định) hiện SỐ THỨ TỰ mọi câu, câu đã trả lời có dấu tích xanh, câu đang xem có
// viền màu primary - bấm số nào nhảy thẳng tới câu đó (không giới hạn đã làm hay chưa, đúng ý "sửa
// đáp án" của anh) + 2 nút "Câu trước"/"Câu tiếp theo" dưới câu hỏi. Sau khi đã NỘP bài
// (`result != null`) GIỮ NGUYÊN kiểu liệt kê hết mọi câu 1 lượt như cũ (đã chốt qua
// AskUserQuestion, không đổi trải nghiệm xem lại). `renderQuestionCard(...)` (khai báo ngay trước
// `return` bên dưới) là nội dung 1 Card câu hỏi DÙNG CHUNG cho cả 2 chế độ - y hệt logic cũ, chỉ
// bọc thành hàm để gọi lại được ở cả `.map()` (xem lại) lẫn hiện đơn lẻ (đang làm). `currentIndex`
// (stream mới trong BlocStudentAttempt) là câu đang xem trong chế độ "đang làm bài" - LUÔN reset về
// 0 mỗi khi start 1 attempt (kể cả resume dở dang).
//
// STATE MANAGEMENT (đổi 2026-09-01, xem claude/ui-base-status.md "Quy ước state mới") - toàn bộ
// useState cục bộ trước đây (attemptId/questions/answers/submitting/result + state Dialog xem lại
// bài học) dời vào BlocStudentAttempt, xem comment ở đó. Trang này không có ô nhập liệu tự do nào
// (chỉ chọn Radio) nên không có nguy cơ giật khi gõ như các trang khác - đổi ở đây thuần để thống
// nhất 1 cách quản lý state duy nhất trong toàn app.
export default function TakeTest() {
    const { t } = useTranslation();
    const { enqueueSnackbar } = useSnackbar();
    const navigate = useNavigate();
    const { testId } = useParams<{ testId: string }>();
    const appContext = useContext(AppContext);
    const bloc = reUseBlocContent(appContext, BlocStudentAttempt);
    const showError = (error: any) => enqueueSnackbar(quizErrorMessage(t, error), { variant: error?.variant ?? 'error' });

    useEffect(() => {
        const id = Number(testId);
        if (!id) return;
        bloc.startAttempt(id, (error) => {
            showError(error);
            navigate('/app/student/tests', { replace: true });
        });
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [testId]);

    const chooseAnswer = (questionId: number, choiceId: number) => bloc.chooseAnswer(questionId, choiceId, showError);
    const askSubmit = () => bloc.doSubmit(showError);
    const openLessonDialog = (lessonId: number) => bloc.openLessonDialog(lessonId, showError);
    const playQuestionAudio = (questionId: number) => bloc.loadQuestionAudio(questionId, showError);
    const playQuestionVideo = (questionId: number) => bloc.loadQuestionVideo(questionId, showError);
    const startRecording = (questionId: number) => bloc.startRecording(questionId, showError);
    // Read attemptId at call time. TakeTest doesn't subscribe to the attemptId stream, so it never
    // re-renders after startAttempt sets it - a top-level const would stay stale (null) and silently
    // block stop/delete/save. Reading inside each handler always sees the current value.
    const stopRecording = (questionId: number) => {
        const attemptId: number | null = bloc.getField('attemptId') ?? null;
        if (attemptId != null) bloc.stopRecording(attemptId, questionId, showError);
    };
    const deleteSpeakingAnswer = (questionId: number) => {
        const attemptId: number | null = bloc.getField('attemptId') ?? null;
        if (attemptId != null) bloc.deleteSpeakingAnswer(attemptId, questionId, showError);
    };
    const saveSpeakingText = (questionId: number, text: string) => {
        const attemptId: number | null = bloc.getField('attemptId') ?? null;
        if (attemptId != null) bloc.saveSpeakingTextAnswer(attemptId, questionId, text, showError);
    };

    // Tách riêng thành 1 hàm (2026-09-06, thiết kế lại giao diện làm bài) - nội dung Card của
    // 1 câu hỏi CŨ chỉ dùng để .map() hiện HẾT mọi câu 1 lượt, GIỜ dùng lại y hệt cho CẢ 2 chỗ:
    // (1) chế độ đang làm bài - chỉ hiện 1 câu (currentQuestion) kèm bảng chọn nhanh + next/prev
    // (theo yêu cầu của anh - tránh cuộn dài với đề nhiều câu); (2) chế độ xem lại SAU KHI đã nộp
    // - vẫn liệt kê hết 1 lượt như cũ (đã chốt qua AskUserQuestion, không đổi trải nghiệm xem lại).
    // Không đổi bất kỳ logic/JSX nào bên trong - nguyên xi nội dung Card cũ, chỉ bọc thành hàm.
    const renderQuestionCard = (q: QuizStudentQuestion, i: number, answers: Record<number, number>, result: any) => (
                                                        <Card key={q.questionId} sx={{ p: { xs: 2, sm: 3 } }}>
                                                            <Stack direction="row" alignItems="flex-start" justifyContent="space-between" gap={1} sx={{ mb: 1 }}>
                                                                <Typography variant="body1" fontWeight={700}>
                                                                    {i + 1}. {q.content ?? (q.hasAudio && q.hasVideo ? t('quiz-question-media-only-hint') : q.hasVideo ? t('quiz-question-video-only-hint') : t('quiz-question-audio-only-hint'))}
                                                                </Typography>
                                                                <Button
                                                                    size="small"
                                                                    startIcon={<MenuBookOutlined />}
                                                                    onClick={() => openLessonDialog(q.lessonId)}
                                                                    sx={{ flexShrink: 0 }}
                                                                >
                                                                    {t('quiz-view-lesson')}
                                                                </Button>
                                                            </Stack>
                                                            {q.hasAudio && (
                                                                <UIStream
                                                                    initialData={null}
                                                                    stream={bloc.getStream('audioUrls')}
                                                                    builder={(urlsSnap) => {
                                                                        const url = (urlsSnap.data ?? {})[q.questionId];
                                                                        if (url) {
                                                                            return <Box component="audio" controls src={url} sx={{ height: 36, mb: 1.5, maxWidth: 320, display: 'block' }} />;
                                                                        }
                                                                        return (
                                                                            <UIStream
                                                                                initialData={null}
                                                                                stream={bloc.getStream('audioLoadingIds')}
                                                                                builder={(loadingSnap) => (
                                                                                    <Button
                                                                                        size="small"
                                                                                        variant="outlined"
                                                                                        startIcon={<VolumeUpOutlined />}
                                                                                        disabled={(loadingSnap.data ?? {})[q.questionId] === true}
                                                                                        onClick={() => playQuestionAudio(q.questionId)}
                                                                                        sx={{ mb: 1.5 }}
                                                                                    >
                                                                                        {(loadingSnap.data ?? {})[q.questionId] === true ? t('quiz-question-audio-loading') : t('quiz-question-audio-play')}
                                                                                    </Button>
                                                                                )}
                                                                            />
                                                                        );
                                                                    }}
                                                                />
                                                            )}
                                                            {q.hasVideo && (
                                                                <UIStream
                                                                    initialData={null}
                                                                    stream={bloc.getStream('videoUrls')}
                                                                    builder={(urlsSnap) => {
                                                                        const url = (urlsSnap.data ?? {})[q.questionId];
                                                                        if (url) {
                                                                            return <Box component="video" controls src={url} sx={{ maxHeight: 240, mb: 1.5, maxWidth: 360, display: 'block' }} />;
                                                                        }
                                                                        return (
                                                                            <UIStream
                                                                                initialData={null}
                                                                                stream={bloc.getStream('videoLoadingIds')}
                                                                                builder={(loadingSnap) => (
                                                                                    <Button
                                                                                        size="small"
                                                                                        variant="outlined"
                                                                                        startIcon={<VideocamOutlined />}
                                                                                        disabled={(loadingSnap.data ?? {})[q.questionId] === true}
                                                                                        onClick={() => playQuestionVideo(q.questionId)}
                                                                                        sx={{ mb: 1.5 }}
                                                                                    >
                                                                                        {(loadingSnap.data ?? {})[q.questionId] === true ? t('quiz-question-video-loading') : t('quiz-question-video-play')}
                                                                                    </Button>
                                                                                )}
                                                                            />
                                                                        );
                                                                    }}
                                                                />
                                                            )}
                                                            {q.questionType === 'SPEAKING' ? (
                                                                <Stack spacing={1}>
                                                                    {q.answerMode !== 'TEXT' && (
                                                                        <>
                                                                            <Typography variant="body2" color="text.secondary">
                                                                                {t('quiz-speaking-hint')}
                                                                            </Typography>
                                                                            <UIStream
                                                                                initialData={null}
                                                                                stream={bloc.getStream('recordingQuestionId')}
                                                                                builder={(recSnap) => {
                                                                                    const recordingId = recSnap.data;
                                                                                    const isRecording = recordingId === q.questionId;
                                                                                    const otherRecording = recordingId != null && recordingId !== q.questionId;
                                                                                    return (
                                                                                        <UIStream
                                                                                            initialData={null}
                                                                                            stream={bloc.getStream('speakingAudioUrls')}
                                                                                            builder={(urlsSnap) => {
                                                                                                const url = (urlsSnap.data ?? {})[q.questionId];
                                                                                                return (
                                                                                                    <UIStream
                                                                                                        initialData={null}
                                                                                                        stream={bloc.getStream('speakingLoadingIds')}
                                                                                                        builder={(loadingSnap) => {
                                                                                                            const loading = (loadingSnap.data ?? {})[q.questionId] === true;
                                                                                                            return (
                                                                                                                <Stack direction="row" alignItems="center" spacing={1} flexWrap="wrap">
                                                                                                                    {isRecording ? (
                                                                                                                        <Button
                                                                                                                            size="small"
                                                                                                                            color="error"
                                                                                                                            variant="contained"
                                                                                                                            startIcon={<StopCircleOutlined />}
                                                                                                                            onClick={() => stopRecording(q.questionId)}
                                                                                                                        >
                                                                                                                            {t('quiz-speaking-stop')}
                                                                                                                        </Button>
                                                                                                                    ) : (
                                                                                                                        <Button
                                                                                                                            size="small"
                                                                                                                            variant="outlined"
                                                                                                                            startIcon={<MicOutlined />}
                                                                                                                            disabled={result != null || loading || otherRecording}
                                                                                                                            onClick={() => startRecording(q.questionId)}
                                                                                                                        >
                                                                                                                            {loading ? t('quiz-speaking-uploading') : url ? t('quiz-speaking-record-again') : t('quiz-speaking-record')}
                                                                                                                        </Button>
                                                                                                                    )}
                                                                                                                    {url && !isRecording && (
                                                                                                                        <>
                                                                                                                            <Box component="audio" controls src={url} sx={{ height: 36, maxWidth: 260 }} />
                                                                                                                            {result == null && (
                                                                                                                                <Button
                                                                                                                                    size="small"
                                                                                                                                    color="error"
                                                                                                                                    startIcon={<DeleteOutlined />}
                                                                                                                                    disabled={loading}
                                                                                                                                    onClick={() => deleteSpeakingAnswer(q.questionId)}
                                                                                                                                >
                                                                                                                                    {t('quiz-speaking-delete')}
                                                                                                                                </Button>
                                                                                                                            )}
                                                                                                                        </>
                                                                                                                    )}
                                                                                                                </Stack>
                                                                                                            );
                                                                                                        }}
                                                                                                    />
                                                                                                );
                                                                                            }}
                                                                                        />
                                                                                    );
                                                                                }}
                                                                            />
                                                                        </>
                                                                    )}
                                                                    {q.answerMode !== 'AUDIO' && (
                                                                        <UIStream
                                                                            initialData={bloc.getField('speakingTextAnswers') ?? {}}
                                                                            stream={bloc.getStream('speakingTextAnswers')}
                                                                            builder={(textSnap) => {
                                                                                const speakingTexts: Record<number, string> = textSnap.data ?? {};
                                                                                const currentText = speakingTexts[q.questionId] ?? q.answerText ?? '';
                                                                                return (
                                                                                    <TextField
                                                                                        label={t('quiz-speaking-text-label')}
                                                                                        placeholder={t('quiz-speaking-text-hint')}
                                                                                        multiline
                                                                                        minRows={2}
                                                                                        fullWidth
                                                                                        disabled={result != null}
                                                                                        defaultValue={currentText}
                                                                                        onBlur={(e) => saveSpeakingText(q.questionId, e.target.value)}
                                                                                    />
                                                                                );
                                                                            }}
                                                                        />
                                                                    )}
                                                                </Stack>
                                                            ) : (
                                                                <RadioGroup
                                                                    value={answers[q.questionId] ?? ''}
                                                                    onChange={(e) => chooseAnswer(q.questionId, Number(e.target.value))}
                                                                >
                                                                    {q.choices.map((c) => (
                                                                        <FormControlLabel
                                                                            key={c.choiceId}
                                                                            value={c.choiceId}
                                                                            control={<Radio disabled={result != null} />}
                                                                            label={c.content}
                                                                        />
                                                                    ))}
                                                                </RadioGroup>
                                                            )}
                                                        </Card>
    );

    return (
        <UIStream
            initialData={bloc.getField('questions') ?? null}
            stream={bloc.getStream('questions')}
            builder={(qSnap) => {
                const questions: QuizStudentQuestion[] | null = qSnap.data;
                if (!questions) {
                    return (
                        <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
                            <CircularProgress />
                        </Box>
                    );
                }

                return (
                    <Stack spacing={2}>
                        <UIStream
                            initialData={null}
                            stream={bloc.getStream('result')}
                            builder={(resultSnap) => {
                                const result = resultSnap.data;
                                if (result) {
                                    return (
                                        <Card sx={{ p: 4, textAlign: 'center' }}>
                                            <CheckCircleOutlined color="success" sx={{ fontSize: 64, mb: 1 }} />
                                            <Typography variant="h5" fontWeight={700} sx={{ mb: 1 }}>{t('quiz-test-submitted')}</Typography>
                                            <Typography variant="h4" fontWeight={700} color="primary.main" sx={{ mb: 1 }}>
                                                {result.correctCount}/{result.totalQuestions}
                                            </Typography>
                                            <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
                                                {t('quiz-score-percent', { percent: Math.round(result.scorePercent) })}
                                            </Typography>
                                            <Button variant="contained" onClick={() => navigate('/app/student/tests')}>{t('quiz-back-to-tests')}</Button>
                                        </Card>
                                    );
                                }
                                return (
                                    <UIStream
                                        initialData={bloc.getField('answers') ?? {}}
                                        stream={bloc.getStream('answers')}
                                        builder={(answersSnap) => {
                                            const answers: Record<number, number> = answersSnap.data ?? {};
                                            return (
                                                <UIStream
                                                    initialData={bloc.getField('speakingAudioUrls') ?? {}}
                                                    stream={bloc.getStream('speakingAudioUrls')}
                                                    builder={(speakingSnap) => {
                                                        const speakingUrls: Record<number, string> = speakingSnap.data ?? {};
                                                        return (
                                                            <UIStream
                                                                initialData={bloc.getField('speakingTextAnswers') ?? {}}
                                                                stream={bloc.getStream('speakingTextAnswers')}
                                                                builder={(speakingTextSnap) => {
                                                                    const speakingTexts: Record<number, string> = speakingTextSnap.data ?? {};
                                                                    // Đếm "đã trả lời" gộp cả 2 loại - câu MULTIPLE_CHOICE tính đã
                                                                    // chọn đáp án, câu SPEAKING tính đã có bản ghi âm HOẶC đã gõ
                                                                    // chữ (không dùng Object.keys(answers).length như cũ vì
                                                                    // 'answers' chỉ chứa câu trắc nghiệm).
                                                                    const answeredCount = questions.filter((q) => q.questionType === 'SPEAKING'
                                                                        ? (speakingUrls[q.questionId] != null || !!speakingTexts[q.questionId]?.trim())
                                                                        : answers[q.questionId] != null).length;
                                                                    // Bat buoc tra loi HET moi duoc nop bai (2026-09-05, theo yeu cau
                                                                    // "cho lam bai cua hoc sinh bat buoc phai tra loi het moi nop bai") -
                                                                    // ap dung cho MOI cau hoi ke ca SPEAKING, dung y het cach dem
                                                                    // answeredCount o tren (khop AskUserQuestion da chot). Nut Nop bai
                                                                    // disable khi con thieu - backend cung tu choi lai lan nua qua
                                                                    // QUIZ_038 ATTEMPT_NOT_ALL_ANSWERED neu goi thang API (xem
                                                                    // StudentAttemptService#assertAllQuestionsAnswered), day chi la lop
                                                                    // chan o frontend cho trai nghiem muot hon.
                                                                    const allAnswered = answeredCount >= questions.length;
                                                                    return (
                                                                        <Card sx={{ p: 2 }}>
                                                                            <Stack direction="row" alignItems="center" justifyContent="space-between" flexWrap="wrap" gap={1}>
                                                                                <Typography variant="subtitle1" fontWeight={700} color={allAnswered ? 'text.primary' : 'error.main'}>
                                                                                    {t('quiz-answered-count', { answered: answeredCount, total: questions.length })}
                                                                                </Typography>
                                                                                <UIStream
                                                                                    initialData={false}
                                                                                    stream={bloc.getStream('submitting')}
                                                                                    builder={(submittingSnap) => (
                                                                                        <Button variant="contained" disabled={submittingSnap.data === true || !allAnswered} onClick={askSubmit}>{t('quiz-submit-test')}</Button>
                                                                                    )}
                                                                                />
                                                                            </Stack>
                                                                            {!allAnswered && (
                                                                                <Typography variant="caption" color="error.main" sx={{ display: 'block', mt: 1 }}>
                                                                                    {t('quiz-answer-all-required')}
                                                                                </Typography>
                                                                            )}
                                                                        </Card>
                                                                    );
                                                                }}
                                                            />
                                                        );
                                                    }}
                                                />
                                            );
                                        }}
                                    />
                                );
                            }}
                        />

                        <UIStream
                            initialData={bloc.getField('answers') ?? {}}
                            stream={bloc.getStream('answers')}
                            builder={(answersSnap) => {
                                const answers: Record<number, number> = answersSnap.data ?? {};
                                return (
                                    <UIStream
                                        initialData={bloc.getField('speakingAudioUrls') ?? {}}
                                        stream={bloc.getStream('speakingAudioUrls')}
                                        builder={(speakingSnap) => {
                                            const speakingUrls: Record<number, string> = speakingSnap.data ?? {};
                                            return (
                                                <UIStream
                                                    initialData={bloc.getField('speakingTextAnswers') ?? {}}
                                                    stream={bloc.getStream('speakingTextAnswers')}
                                                    builder={(speakingTextSnap) => {
                                                        const speakingTexts: Record<number, string> = speakingTextSnap.data ?? {};
                                                        return (
                                                            <UIStream
                                                                initialData={null}
                                                                stream={bloc.getStream('result')}
                                                                builder={(resultSnap) => {
                                                                    const result = resultSnap.data;

                                                                    // Sau khi đã NỘP bài - GIỮ NGUYÊN kiểu liệt kê hết 1 lượt như cũ
                                                                    // (không áp dụng giao diện "1 câu/màn hình" cho chế độ xem lại -
                                                                    // đã chốt qua AskUserQuestion 2026-09-06).
                                                                    if (result != null) {
                                                                        return (
                                                                            <Stack spacing={2}>
                                                                                {questions.map((q, i) => renderQuestionCard(q, i, answers, result))}
                                                                            </Stack>
                                                                        );
                                                                    }

                                                                    // ĐANG làm bài (2026-09-06, thiết kế lại theo yêu cầu của anh:
                                                                    // "next, prev từng câu, những câu nào đã làm thì đánh dấu check, có
                                                                    // thể bấm câu chưa làm hoặc đã làm để move đến câu đó làm/sửa đáp
                                                                    // án") - CHỈ hiện 1 câu/màn hình (tránh cuộn dài với đề nhiều câu) +
                                                                    // 1 bảng chọn nhanh (hàng ngang, tự xuống dòng - đã chọn qua
                                                                    // AskUserQuestion, không dùng sidebar) phía trên + nút Câu trước/
                                                                    // Câu tiếp theo phía dưới.
                                                                    return (
                                                                        <UIStream
                                                                            initialData={bloc.getField('currentIndex') ?? 0}
                                                                            stream={bloc.getStream('currentIndex')}
                                                                            builder={(idxSnap) => {
                                                                                const currentIndex = idxSnap.data ?? 0;
                                                                                const currentQuestion = questions[currentIndex];
                                                                                return (
                                                                                    <Stack spacing={2}>
                                                                                        <Card sx={{ p: 2 }}>
                                                                                            <Typography variant="subtitle2" fontWeight={700} sx={{ mb: 1.5 }}>
                                                                                                {t('quiz-question-navigator')}
                                                                                            </Typography>
                                                                                            <Stack direction="row" flexWrap="wrap" gap={1} sx={{ mb: 1.5 }}>
                                                                                                {questions.map((qq, qi) => {
                                                                                                    const isAnswered = qq.questionType === 'SPEAKING'
                                                                                                        ? (speakingUrls[qq.questionId] != null || !!speakingTexts[qq.questionId]?.trim())
                                                                                                        : answers[qq.questionId] != null;
                                                                                                    const isCurrent = qi === currentIndex;
                                                                                                    return (
                                                                                                        <ButtonBase
                                                                                                            key={qq.questionId}
                                                                                                            onClick={() => bloc.goToQuestion(qi)}
                                                                                                            sx={{
                                                                                                                width: 40, height: 40, borderRadius: 1.5, position: 'relative',
                                                                                                                display: 'flex', alignItems: 'center', justifyContent: 'center',
                                                                                                                border: '2px solid',
                                                                                                                borderColor: isCurrent ? 'primary.main' : (isAnswered ? 'success.main' : 'divider'),
                                                                                                                bgcolor: isAnswered ? 'success.light' : 'transparent',
                                                                                                                color: isAnswered ? 'success.dark' : 'text.primary',
                                                                                                                '&:hover': { bgcolor: isAnswered ? 'success.light' : 'action.hover' }
                                                                                                            }}
                                                                                                        >
                                                                                                            <Typography variant="body2" fontWeight={700}>{qi + 1}</Typography>
                                                                                                            {isAnswered && (
                                                                                                                <CheckCircleOutlined
                                                                                                                    sx={{
                                                                                                                        position: 'absolute', top: -6, right: -6, fontSize: 16,
                                                                                                                        color: 'success.main', bgcolor: 'background.paper', borderRadius: '50%'
                                                                                                                    }}
                                                                                                                />
                                                                                                            )}
                                                                                                        </ButtonBase>
                                                                                                    );
                                                                                                })}
                                                                                            </Stack>
                                                                                            <Stack direction="row" spacing={2} flexWrap="wrap">
                                                                                                <Stack direction="row" alignItems="center" spacing={0.5}>
                                                                                                    <Box sx={{ width: 14, height: 14, borderRadius: 0.5, border: '2px solid', borderColor: 'success.main', bgcolor: 'success.light' }} />
                                                                                                    <Typography variant="caption" color="text.secondary">{t('quiz-question-answered-legend')}</Typography>
                                                                                                </Stack>
                                                                                                <Stack direction="row" alignItems="center" spacing={0.5}>
                                                                                                    <Box sx={{ width: 14, height: 14, borderRadius: 0.5, border: '2px solid', borderColor: 'divider' }} />
                                                                                                    <Typography variant="caption" color="text.secondary">{t('quiz-question-unanswered-legend')}</Typography>
                                                                                                </Stack>
                                                                                                <Stack direction="row" alignItems="center" spacing={0.5}>
                                                                                                    <Box sx={{ width: 14, height: 14, borderRadius: 0.5, border: '2px solid', borderColor: 'primary.main' }} />
                                                                                                    <Typography variant="caption" color="text.secondary">{t('quiz-question-current-legend')}</Typography>
                                                                                                </Stack>
                                                                                            </Stack>
                                                                                        </Card>

                                                                                        {renderQuestionCard(currentQuestion, currentIndex, answers, result)}

                                                                                        <Stack direction="row" justifyContent="space-between">
                                                                                            <Button
                                                                                                variant="outlined"
                                                                                                disabled={currentIndex === 0}
                                                                                                onClick={() => bloc.prevQuestion()}
                                                                                            >
                                                                                                {t('quiz-prev-question')}
                                                                                            </Button>
                                                                                            <Button
                                                                                                variant="outlined"
                                                                                                disabled={currentIndex === questions.length - 1}
                                                                                                onClick={() => bloc.nextQuestion(questions.length)}
                                                                                            >
                                                                                                {t('quiz-next-question')}
                                                                                            </Button>
                                                                                        </Stack>
                                                                                    </Stack>
                                                                                );
                                                                            }}
                                                                        />
                                                                    );
                                                                }}
                                                            />
                                                        );
                                                    }}
                                                />
                                            );
                                        }}
                                    />
                                );
                            }}
                        />

                        <UIStream
                            initialData={{ isShow: false }}
                            stream={bloc.getStream('lesson_dialog_view')}
                            builder={(viewSnap) => {
                                const view = viewSnap.data ?? { isShow: false };
                                return (
                                    <AppDialog
                                        open={view.isShow === true}
                                        onClose={() => bloc.closeLessonDialog()}
                                        maxWidth="sm"
                                        icon={MenuBookOutlined}
                                        title={
                                            <UIStream
                                                initialData={null}
                                                stream={bloc.getStream('lessonData')}
                                                builder={(lessonSnap) => <>{lessonSnap.data?.name ?? t('quiz-view-lesson')}</>}
                                            />
                                        }
                                    >
                                        <DialogContent>
                                            <UIStream
                                                initialData={false}
                                                stream={bloc.getStream('lessonLoading')}
                                                builder={(loadingSnap) => {
                                                    if (loadingSnap.data === true) {
                                                        return (
                                                            <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
                                                                <CircularProgress />
                                                            </Box>
                                                        );
                                                    }
                                                    return (
                                                        <UIStream
                                                            initialData={null}
                                                            stream={bloc.getStream('lessonData')}
                                                            builder={(lessonSnap) => {
                                                                const lessonData = lessonSnap.data;
                                                                if (!lessonData) return null;
                                                                return (
                                                                    <UIStream
                                                                        initialData={null}
                                                                        stream={bloc.getStream('lessonImageUrl')}
                                                                        builder={(imageSnap) => {
                                                                            const lessonImageUrl = imageSnap.data;
                                                                            return (
                                                                                <UIStream
                                                                                    initialData={null}
                                                                                    stream={bloc.getStream('lessonAttachments')}
                                                                                    builder={(attachmentsSnap) => {
                                                                                        const attachments: QuizLessonAttachment[] = attachmentsSnap.data ?? [];
                                                                                        return (
                                                                                    <Stack spacing={2} sx={{ mt: 1 }}>
                                                                                        {lessonImageUrl && (
                                                                                            <Box
                                                                                                component="img"
                                                                                                src={lessonImageUrl}
                                                                                                alt={lessonData.name}
                                                                                                sx={{ width: '100%', maxHeight: 280, objectFit: 'contain', borderRadius: 1 }}
                                                                                            />
                                                                                        )}
                                                                                        {lessonData.textbookPage != null && (
                                                                                            <Typography variant="body2" color="text.secondary">
                                                                                                {t('quiz-lesson-textbook-page')}: {lessonData.textbookPage}
                                                                                            </Typography>
                                                                                        )}
                                                                                        {lessonData.summary && (
                                                                                            <Box>
                                                                                                <Typography variant="subtitle2">{t('quiz-lesson-summary')}</Typography>
                                                                                                <Typography variant="body2" sx={{ whiteSpace: 'pre-wrap' }}>{lessonData.summary}</Typography>
                                                                                            </Box>
                                                                                        )}
                                                                                        {lessonData.content && (
                                                                                            <Box>
                                                                                                <Typography variant="subtitle2">{t('quiz-lesson-content')}</Typography>
                                                                                                <Typography variant="body2" sx={{ whiteSpace: 'pre-wrap' }}>{lessonData.content}</Typography>
                                                                                            </Box>
                                                                                        )}
                                                                                            {attachments.length > 0 && (
                                                                                                <Box>
                                                                                                    <Typography variant="subtitle2">{t('quiz-lesson-attachments')}</Typography>
                                                                                                    <List dense disablePadding>
                                                                                                        {attachments.map((a) => (
                                                                                                            <ListItem
                                                                                                                key={a.id}
                                                                                                                disableGutters
                                                                                                                secondaryAction={
                                                                                                                    <Stack direction="row" spacing={0.5}>
                                                                                                                        <IconButton size="small" onClick={() => bloc.viewLessonAttachmentFile(lessonData.id, a.id, showError)}>
                                                                                                                            <VisibilityOutlined fontSize="small" />
                                                                                                                        </IconButton>
                                                                                                                        <IconButton size="small" onClick={() => bloc.downloadLessonAttachmentFile(lessonData.id, a.id, a.originalName, showError)}>
                                                                                                                            <DownloadOutlined fontSize="small" />
                                                                                                                        </IconButton>
                                                                                                                    </Stack>
                                                                                                                }
                                                                                                            >
                                                                                                                <InsertDriveFileOutlined fontSize="small" sx={{ mr: 1, opacity: 0.6 }} />
                                                                                                                <ListItemText primary={a.originalName} />
                                                                                                            </ListItem>
                                                                                                        ))}
                                                                                                    </List>
                                                                                                </Box>
                                                                                            )}
                                                                                        {!lessonData.summary && !lessonData.content && !lessonImageUrl && attachments.length === 0 && (
                                                                                            <Typography variant="body2" color="text.secondary">{t('quiz-lesson-no-content')}</Typography>
                                                                                        )}
                                                                                    </Stack>
                                                                                        );
                                                                                    }}
                                                                                />
                                                                            );
                                                                        }}
                                                                    />
                                                                );
                                                            }}
                                                        />
                                                    );
                                                }}
                                            />
                                        </DialogContent>
                                        <DialogActions>
                                            <Button onClick={() => bloc.closeLessonDialog()} variant="contained" color="primary" startIcon={<CloseOutlined />} sx={DIALOG_PRIMARY_BUTTON_SX}>{t('close')}</Button>
                                        </DialogActions>
                                    </AppDialog>
                                );
                            }}
                        />
                    </Stack>
                );
            }}
        />
    );
}